{
  "name": "postgres-mcp",
  "type": "mcpserver",
  "version": "1.0.0",
  "description": "Model Context Protocol (MCP) Server for PostgreSQL database inspection and query execution.",
  "mcpServers": {
    "postgres": {
      "command": "npx",
      "args": ["-y", "@modelcontextprotocol/server-postgres", "postgresql://localhost:5432/main"]
    }
  }
}
